use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,io::Write,path::Path};
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn main(){for label in["frozen","fresh","selected"]{let text=fs::read_to_string(format!("native/{label}-build/stdout.log")).unwrap();let root=Path::new("frozen-libraries").join(label);let mut pins=BTreeMap::new();let mut original=BTreeMap::new();for line in text.lines(){let v:Value=serde_json::from_str(line).unwrap();if v["reason"]!="compiler-artifact"||!v["target"]["kind"].as_array().unwrap().iter().any(|s|s=="proc-macro"){continue}for file in v["filenames"].as_array().unwrap().iter().filter_map(Value::as_str){let path=Path::new(file);assert_eq!(path.extension().unwrap(),"so");let bytes=fs::read(path).unwrap();let h=hash(&bytes);let dest=root.join(path.file_name().unwrap());match fs::OpenOptions::new().write(true).create_new(true).open(&dest){Ok(mut f)=>f.write_all(&bytes).unwrap(),Err(e)if e.kind()==std::io::ErrorKind::AlreadyExists=>assert_eq!(fs::read(&dest).unwrap(),bytes),Err(e)=>panic!("{e}")}assert_eq!(fs::read(&dest).unwrap(),bytes);let dest=fs::canonicalize(dest).unwrap().display().to_string();pins.insert(dest,h.clone());original.insert(file.to_string(),h);}}assert!(!pins.is_empty());fs::write(format!("native/{label}-proc-macros.json"),serde_json::to_vec_pretty(&json!({"label":label,"input_pins":pins,"original_inputs":original,"Cargo_artifacts_sha256":hash(text.as_bytes()),"repair_scope":"missing proc-macro artifacts only; no Cargo rebuild/test or measurement repeated"})).unwrap()).unwrap();}println!("Frozeproc-macrosharedlibrariesforall3variants");}
